import React, { useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import sr from '@utils/sr';
import { srConfig } from '@config';
import { Heading } from '@styles';
import { useProjectFilter } from '@hooks';
import TagsList from '../subsections/TagsList';
import ProjectList from '../subsections/ProjectList';
import "react-responsive-carousel/lib/styles/carousel.min.css";
import 'bootstrap/dist/css/bootstrap.min.css';

import {
  StyledContainer,
} from '../styles/featured-style';

const Featured = ({ data, projectOrder }) => {

  const featuredProjects = data.filter(({ node }) => node);

  // Use the project filter hook for advanced filtering
  const {
    selectedTags,
    filterMode,
    allTags,
    tagCounts,
    filteredProjects,
    toggleTag,
    clearFilters,
    toggleFilterMode,
    totalProjects,
    filteredCount,
  } = useProjectFilter(featuredProjects, projectOrder);

  const revealTitle = useRef(null);
  const revealProjects = useRef([]);

  useEffect(() => {
    sr.reveal(revealTitle.current, srConfig());
    revealProjects.current.forEach((ref, i) => sr.reveal(ref, srConfig(i * 100)));
  }, []);

  return (
    <StyledContainer id="projects">
      <Heading ref={revealTitle}>Some Things I&apos;ve Built</Heading>
      <TagsList
        allTags={allTags}
        selectedTags={selectedTags}
        tagCounts={tagCounts}
        filterMode={filterMode}
        onTagClick={toggleTag}
        onFilterModeToggle={toggleFilterMode}
        onClearFilters={clearFilters}
        filteredCount={filteredCount}
        totalProjects={totalProjects}
      />
      <ProjectList projects={filteredProjects} revealProjects={revealProjects} />
    </StyledContainer>
  );
};

Featured.propTypes = {
  data: PropTypes.array.isRequired,
  projectOrder: PropTypes.array.isRequired,
};

export default Featured;
