import { useEffect, useCallback } from 'react';

/**
 * Custom hook for adding a tilt effect to an element on mouse move
 * @param {React.RefObject} ref - Reference to the element to apply tilt
 * @param {Object} options - Configuration options
 * @param {number} options.maxTilt - Maximum tilt angle in degrees (default: 10)
 * @param {number} options.scale - Scale factor on hover (default: 1.02)
 * @param {number} options.speed - Transition speed in ms (default: 400)
 * @param {boolean} options.disabled - Disable the effect (default: false)
 */
const useTilt = (ref, options = {}) => {
  const {
    maxTilt = 10,
    scale = 1.02,
    speed = 400,
    disabled = false,
  } = options;

  const isTouchDevice = useCallback(() => {
    if (typeof window === 'undefined') return false;
    return 'ontouchstart' in window || navigator.maxTouchPoints > 0;
  }, []);

  useEffect(() => {
    const element = ref.current;
    if (!element || disabled || isTouchDevice()) return;

    const handleMouseMove = (e) => {
      const rect = element.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;

      // Calculate mouse position relative to center (-1 to 1)
      const mouseX = (e.clientX - centerX) / (rect.width / 2);
      const mouseY = (e.clientY - centerY) / (rect.height / 2);

      // Calculate tilt angles (inverted for natural feel)
      const tiltX = -mouseY * maxTilt;
      const tiltY = mouseX * maxTilt;

      element.style.transform = `perspective(1000px) rotateX(${tiltX}deg) rotateY(${tiltY}deg) scale(${scale})`;
    };

    const handleMouseEnter = () => {
      element.style.transition = `transform ${speed}ms ease-out`;
    };

    const handleMouseLeave = () => {
      element.style.transition = `transform ${speed}ms ease-out`;
      element.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) scale(1)';
    };

    element.addEventListener('mousemove', handleMouseMove);
    element.addEventListener('mouseenter', handleMouseEnter);
    element.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      element.removeEventListener('mousemove', handleMouseMove);
      element.removeEventListener('mouseenter', handleMouseEnter);
      element.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, [ref, maxTilt, scale, speed, disabled, isTouchDevice]);
};

export default useTilt;
