import { useState, useEffect, useRef } from 'react';

/**
 * Custom hook for animating a number counting up when element is in view
 * @param {number} end - The final number to count to
 * @param {number} duration - Duration of animation in ms (default 2000)
 * @param {number} start - Starting number (default 0)
 * @returns {Object} - { count, ref, isInView }
 */
const useCountUp = (end, duration = 2000, start = 0) => {
  const [count, setCount] = useState(start);
  const [isInView, setIsInView] = useState(false);
  const [hasAnimated, setHasAnimated] = useState(false);
  const ref = useRef(null);

  // Check for reduced motion preference
  const prefersReducedMotion =
    typeof window !== 'undefined' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Intersection Observer to detect when element is in view
  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasAnimated) {
          setIsInView(true);
        }
      },
      { threshold: 0.3 }
    );

    observer.observe(element);
    return () => observer.disconnect();
  }, [hasAnimated]);

  // Animate the count when in view
  useEffect(() => {
    if (!isInView || hasAnimated) return;

    // If user prefers reduced motion, show final number immediately
    if (prefersReducedMotion) {
      setCount(end);
      setHasAnimated(true);
      return;
    }

    const startTime = Date.now();
    const endValue = end;
    const startValue = start;

    const animate = () => {
      const now = Date.now();
      const progress = Math.min((now - startTime) / duration, 1);

      // Easing function (ease-out)
      const easeOutQuad = 1 - Math.pow(1 - progress, 2);

      const currentCount = Math.floor(startValue + (endValue - startValue) * easeOutQuad);
      setCount(currentCount);

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        setCount(endValue);
        setHasAnimated(true);
      }
    };

    requestAnimationFrame(animate);
  }, [isInView, end, duration, start, hasAnimated, prefersReducedMotion]);

  return { count, ref, isInView };
};

export default useCountUp;
