import React, { useState, useEffect, useMemo } from 'react';
import { Link } from 'gatsby';
import Helmet from 'react-helmet';
import PropTypes from 'prop-types';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import { throttle } from '@utils';
import { defaultProfile, profileToNavLinks, profileToResumeLink, navHeight, profileToNavButton } from '@config';
import { Menu } from '@components';
import { IconLogo, IconSun, IconMoon } from '@components/icons';
import styled from 'styled-components';
import { theme, mixins, media } from '@styles';
import { useLocation } from '@reach/router';
import { useTheme } from '@context';
import { useActiveSection } from '@hooks';
const { colors, fontSizes, fonts, loaderDelay } = theme;

const StyledProgressBar = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: ${props => props.progress}%;
  height: 3px;
  background: linear-gradient(90deg, var(--color-accent) 0%, var(--color-accent) 100%);
  z-index: 13;
  transition: width 0.1s ease-out;
`;

const StyledContainer = styled.header`
  ${mixins.flexBetween};
  position: fixed;
  top: 0;
  padding: 0px 50px;
  background-color: rgba(var(--color-bg-rgb, 10, 25, 47), 0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: ${theme.transition};
  z-index: 11;
  filter: none !important;
  pointer-events: auto !important;
  user-select: auto !important;
  width: 100%;
  height: ${props => (props.scrollDirection === 'none' ? theme.navHeight : theme.navScrollHeight)};
  box-shadow: ${props =>
        props.scrollDirection === 'up' ? `0 10px 30px -10px var(--color-shadow)` : 'none'};
  transform: translateY(
    ${props => (props.scrollDirection === 'down' ? `-${theme.navScrollHeight}` : '0px')}
  );
  ${media.desktop`padding: 0 40px;`};
  ${media.tablet`padding: 0 25px;`};
`;
const StyledNav = styled.nav`
  ${mixins.flexBetween};
  position: relative;
  width: 100%;
  color: var(--color-text-lightest);
  font-family: ${fonts.SFMono};
  counter-reset: item 0;
  z-index: 12;
`;
const StyledLogo = styled.div`
  ${mixins.flexCenter};
  a {
    display: block;
    color: var(--color-accent);
    width: 42px;
    height: 42px;
    &:hover,
    &:focus {
      svg {
        fill: var(--color-accent-tint);
      }
    }
    svg {
      fill: none;
      transition: ${theme.transition};
      user-select: none;
    }
  }
`;
const StyledHamburger = styled.div`
  ${mixins.flexCenter};
  overflow: visible;
  margin: 0 -12px 0 0;
  padding: 15px;
  cursor: pointer;
  transition-timing-function: linear;
  transition-duration: 0.15s;
  transition-property: opacity, filter;
  text-transform: none;
  color: inherit;
  border: 0;
  background-color: transparent;
  display: none;
  ${media.tablet`display: flex;`};
`;
const StyledHamburgerBox = styled.div`
  position: relative;
  display: inline-block;
  width: ${theme.hamburgerWidth}px;
  height: 24px;
`;
const StyledHamburgerInner = styled.div`
  background-color: var(--color-accent);
  position: absolute;
  width: ${theme.hamburgerWidth}px;
  height: 2px;
  border-radius: ${theme.borderRadius};
  top: 50%;
  left: 0;
  right: 0;
  transition-duration: 0.22s;
  transition-property: transform;
  transition-delay: ${props => (props.menuOpen ? `0.12s` : `0s`)};
  transform: rotate(${props => (props.menuOpen ? `225deg` : `0deg`)});
  transition-timing-function: cubic-bezier(
    ${props => (props.menuOpen ? `0.215, 0.61, 0.355, 1` : `0.55, 0.055, 0.675, 0.19`)}
  );
  &:before,
  &:after {
    content: '';
    display: block;
    background-color: var(--color-accent);
    position: absolute;
    left: auto;
    right: 0;
    width: ${theme.hamburgerWidth}px;
    height: 2px;
    transition-timing-function: ease;
    transition-duration: 0.15s;
    transition-property: transform;
    border-radius: 4px;
  }
  &:before {
    width: ${props => (props.menuOpen ? `100%` : `120%`)};
    top: ${props => (props.menuOpen ? `0` : `-10px`)};
    opacity: ${props => (props.menuOpen ? 0 : 1)};
    transition: ${props => (props.menuOpen ? theme.hamBeforeActive : theme.hamBefore)};
  }
  &:after {
    width: ${props => (props.menuOpen ? `100%` : `80%`)};
    bottom: ${props => (props.menuOpen ? `0` : `-10px`)};
    transform: rotate(${props => (props.menuOpen ? `-90deg` : `0`)});
    transition: ${props => (props.menuOpen ? theme.hamAfterActive : theme.hamAfter)};
  }
`;
const StyledLink = styled.div`
  display: flex;
  align-items: center;
  ${media.tablet`display: none;`};
`;
const StyledList = styled.ol`
  ${mixins.flexBetween};
  padding: 0;
  margin: 0;
  list-style: none;
`;
const StyledListItem = styled.li`
  margin: 0 10px;
  position: relative;
  font-size: ${fontSizes.smish};
  counter-increment: item 1;
  &:before {
    content: '0' counter(item) '.';
    text-align: right;
    color: var(--color-accent);
    font-size: ${fontSizes.xs};
  }
`;
const StyledListLink = styled(Link)`
  padding: 12px 10px;
  position: relative;

  &.active {
    color: var(--color-accent);
  }

  &.active::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    background-color: var(--color-accent);
    border-radius: 1px;
  }
`;
const StyledResumeButton = styled.a`
  ${mixins.smallButton};
  margin-left: 10px;
  font-size: ${fontSizes.smish};
`;
const StyledThemeToggle = styled.button`
  ${mixins.flexCenter};
  background: transparent;
  border: none;
  padding: 10px;
  margin-left: 10px;
  cursor: pointer;
  color: var(--color-accent);
  transition: ${theme.transition};

  &:hover,
  &:focus {
    color: var(--color-accent);
    transform: translateY(-2px);
  }

  svg {
    width: 20px;
    height: 20px;
  }
`;

const DELTA = 5;

const Nav = ({ isHome, location }) => {
    const [isMounted, setIsMounted] = useState(false);
    const [menuOpen, setMenuOpen] = useState(false);
    const [scrollDirection, setScrollDirection] = useState('none');
    const [lastScrollTop, setLastScrollTop] = useState(0);
    const [scrollProgress, setScrollProgress] = useState(0);
    const { isDarkMode, toggleTheme } = useTheme();

    // Get nav links based on profile
    const winLocation = useLocation();
    const profile = location.pathname.replaceAll("/", "") || defaultProfile;
    const navLinks = profileToNavLinks[profile];

    // Extract section IDs from nav links (remove the # prefix)
    const sectionIds = useMemo(() => {
        if (!navLinks) return [];
        return navLinks
            .map(link => link.url.startsWith('#') ? link.url.substring(1) : null)
            .filter(Boolean);
    }, [navLinks]);

    // Track active section using Intersection Observer
    const activeSection = useActiveSection(sectionIds, 100);

    useEffect(() => {
        setIsMounted(true);
        window.addEventListener('scroll', handleScroll);
        window.addEventListener('resize', handleResize);
        window.addEventListener('keydown', handleKeydown);
        return () => {
            window.removeEventListener('scroll', handleScroll);
            window.removeEventListener('resize', handleResize);
            window.removeEventListener('keydown', handleKeydown);
        };
    }, []);

    const toggleMenu = () => setMenuOpen(!menuOpen);

    const handleScroll = () => {
        const fromTop = window.scrollY;

        // Calculate scroll progress
        const docHeight = document.documentElement.scrollHeight;
        const winHeight = window.innerHeight;
        const scrollableHeight = docHeight - winHeight;
        const progress = scrollableHeight > 0 ? (fromTop / scrollableHeight) * 100 : 0;
        setScrollProgress(Math.min(100, Math.max(0, progress)));

        if (!isMounted || Math.abs(lastScrollTop - fromTop) <= DELTA || menuOpen) {
            return;
        }
        if (fromTop < DELTA) {
            setScrollDirection('none');
        } else if (fromTop > lastScrollTop && fromTop > navHeight) {
            if (scrollDirection !== 'down') {
                setScrollDirection('down');
            }
        } else if (fromTop + window.innerHeight < document.body.scrollHeight) {
            if (scrollDirection !== 'up') {
                setScrollDirection('up');
            }
        }
        setLastScrollTop(fromTop);
    };

    const handleResize = () => {
        if (window.innerWidth > 768 && menuOpen) {
            toggleMenu();
        }
    };

    const handleKeydown = e => {
        if (!menuOpen) {
            return;
        }
        if (e.which === 27 || e.key === 'Escape') {
            toggleMenu();
        }
    };

    const resumeLink = profileToResumeLink[profile];
    const navButton = profileToNavButton[profile];
    const timeout = isHome ? loaderDelay : 0;
    const fadeClass = isHome ? 'fade' : '';
    const fadeDownClass = isHome ? 'fadedown' : '';

    return (
        <>
            <StyledProgressBar progress={scrollProgress} />
            <StyledContainer scrollDirection={scrollDirection}>
            <Helmet>
                <body className={menuOpen ? 'blur' : ''} />
            </Helmet>
            <StyledNav>
                <TransitionGroup component={null}>
                    {isMounted && (
                        <CSSTransition classNames={fadeClass} timeout={timeout}>
                            <StyledLogo tabindex="-1">
                                {isHome ? (
                                    <a href="/" aria-label="home">
                                        <IconLogo />
                                    </a>
                                ) : (
                                    <Link to="/" aria-label="home">
                                        <IconLogo />
                                    </Link>
                                )}
                            </StyledLogo>
                        </CSSTransition>
                    )}
                </TransitionGroup>

                <TransitionGroup component={null}>
                    {isMounted && (
                        <CSSTransition classNames={fadeClass} timeout={timeout}>
                            <StyledHamburger onClick={toggleMenu}>
                                <StyledHamburgerBox>
                                    <StyledHamburgerInner menuOpen={menuOpen} />
                                </StyledHamburgerBox>
                            </StyledHamburger>
                        </CSSTransition>
                    )}
                </TransitionGroup>

                <StyledLink>
                    <StyledList>
                        <TransitionGroup component={null}>
                            {isMounted &&
                                navLinks &&
                                navLinks.map(({ url, name }, i) => (
                                    <CSSTransition key={i} classNames={fadeDownClass} timeout={timeout}>
                                        <StyledListItem
                                            key={i}
                                            style={{ transitionDelay: `${isHome ? i * 100 : 0}ms` }}>
                                            <StyledListLink
                                                to={`${winLocation.pathname}${url}`}
                                                className={url.startsWith('#') && activeSection === url.substring(1) ? 'active' : ''}
                                                onClick={(e) => {
                                                    // Extract the hash from the URL
                                                    const hash = url; // url is already in format "#section"
                                                    if (hash.startsWith('#')) {
                                                        const sectionId = hash.substring(1);
                                                        const element = document.getElementById(sectionId);
                                                        if (element) {
                                                            // Prevent default link behavior
                                                            e.preventDefault();
                                                            // Scroll to the element
                                                            element.scrollIntoView({ behavior: 'smooth' });
                                                            // Update the URL hash
                                                            window.history.pushState(null, null, `${winLocation.pathname}${hash}`);
                                                        }
                                                    }
                                                }}
                                            >
                                                {name}
                                            </StyledListLink>
                                        </StyledListItem>
                                    </CSSTransition>
                                ))}
                        </TransitionGroup>
                    </StyledList>

                    <TransitionGroup component={null}>
                        {isMounted && (
                            <CSSTransition classNames={fadeDownClass} timeout={timeout}>
                                <div style={{ transitionDelay: `${isHome ? navLinks.length * 100 : 0}ms` }}>
                                    <StyledResumeButton
                                        href={navButton.url}
                                        target="_blank"
                                        rel="nofollow noopener noreferrer">
                                        {navButton.text}
                                    </StyledResumeButton>
                                </div>
                            </CSSTransition>
                        )}
                    </TransitionGroup>

                    <TransitionGroup component={null}>
                        {isMounted && (
                            <CSSTransition classNames={fadeDownClass} timeout={timeout}>
                                <div style={{ transitionDelay: `${isHome ? (navLinks.length + 1) * 100 : 0}ms` }}>
                                    <StyledThemeToggle
                                        onClick={toggleTheme}
                                        aria-label={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}
                                        title={isDarkMode ? 'Switch to light mode' : 'Switch to dark mode'}>
                                        {isDarkMode ? <IconSun /> : <IconMoon />}
                                    </StyledThemeToggle>
                                </div>
                            </CSSTransition>
                        )}
                    </TransitionGroup>
                </StyledLink>
            </StyledNav>

            <Menu menuOpen={menuOpen} toggleMenu={toggleMenu} />
        </StyledContainer>
        </>
    )
};

