import React, { useState, useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import sr from '@utils/sr';
import { srConfig } from '@config';
import styled from 'styled-components';
import { Heading, theme, media } from '@styles';
import {
  StyledContainer,
  StyledTabs,
  StyledTabList,
  StyledHighlight,
} from '../styles/education-styles';
import TabButton from '../subsections/EducationTabButton';
import TabContent from '../subsections/EducationTabContent';
import Timeline from '../Timeline';

const StyledViewToggle = styled.div`
  display: flex;
  justify-content: flex-end;
  margin-bottom: 20px;
  gap: 5px;

  ${media.tablet`justify-content: center;`}
`;

const StyledToggleButton = styled.button`
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 8px 12px;
  background-color: ${props => (props.$isActive ? 'var(--color-accent-tint)' : 'transparent')};
  border: 1px solid ${props => (props.$isActive ? 'var(--color-accent)' : 'var(--color-bg-lightest)')};
  border-radius: ${theme.borderRadius};
  color: ${props => (props.$isActive ? 'var(--color-accent)' : 'var(--color-text-light)')};
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.xs};
  cursor: pointer;
  transition: ${theme.transition};

  &:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

  svg {
    width: 14px;
    height: 14px;
  }
`;

const Education = ({ data }) => {
  const [activeTabId, setActiveTabId] = useState(0);
  const [tabFocus, setTabFocus] = useState(null);
  const [viewMode, setViewMode] = useState('tabs'); // 'tabs' or 'timeline'
  const tabs = useRef([]);
  const [viewFactor, setViewFactor] = useState(0.25);

  const revealContainer = useRef(null);
  useEffect(() => sr.reveal(revealContainer.current, srConfig(200, viewFactor)), []);

  const focusTab = () => {
    if (tabs.current[tabFocus]) {
      tabs.current[tabFocus].focus();
    } else {
      // If we're at the end, go to the start
      if (tabFocus >= tabs.current.length) {
        setTabFocus(0);
      }
      // If we're at the start, move to the end
      if (tabFocus < 0) {
        setTabFocus(tabs.current.length - 1);
      }
    }
  };
  // Only re-run the effect if tabFocus changes
  useEffect(() => focusTab(), [tabFocus]);

  const onKeyPressed = e => {
    if (e.keyCode === 38 || e.keyCode === 40) {
      e.preventDefault();
      if (e.keyCode === 40) {
        // Move down
        setTabFocus(tabFocus + 1);
      } else if (e.keyCode === 38) {
        // Move up
        setTabFocus(tabFocus - 1);
      }
    }
  };

  return (
    <StyledContainer id="education" ref={revealContainer}>
      <Heading>Where I&apos;ve Studied</Heading>

      <StyledViewToggle>
        <StyledToggleButton
          $isActive={viewMode === 'tabs'}
          onClick={() => setViewMode('tabs')}
          aria-label="Tab view"
          title="Tab view">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <rect x="3" y="3" width="7" height="7" />
            <rect x="14" y="3" width="7" height="7" />
            <rect x="3" y="14" width="7" height="7" />
            <rect x="14" y="14" width="7" height="7" />
          </svg>
          Tabs
        </StyledToggleButton>
        <StyledToggleButton
          $isActive={viewMode === 'timeline'}
          onClick={() => setViewMode('timeline')}
          aria-label="Timeline view"
          title="Timeline view">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <line x1="12" y1="2" x2="12" y2="22" />
            <circle cx="12" cy="6" r="2" />
            <circle cx="12" cy="12" r="2" />
            <circle cx="12" cy="18" r="2" />
          </svg>
          Timeline
        </StyledToggleButton>
      </StyledViewToggle>

      {viewMode === 'tabs' ? (
        <StyledTabs>
          <StyledTabList role="tablist" aria-label="Education tabs" onKeyDown={e => onKeyPressed(e)}>
            {data &&
              data.map(({ node }, i) => (
                <li key={i}>
                  <TabButton
                    isActive={activeTabId === i}
                    onClick={() => setActiveTabId(i)}
                    ref={(el) => (tabs.current[i] = el)}
                    id={`tab-${i}`}
                    tabIndex={activeTabId === i ? '0' : '-1'}
                  >
                    {node.frontmatter.shortname}
                  </TabButton>
                </li>
              ))}
            <StyledHighlight activeTabId={activeTabId} />
          </StyledTabList>

          {data &&
            data.map(({ node }, i) => (
              <TabContent
                key={i}
                isActive={activeTabId === i}
                node={node}
                id={`panel-${i}`}
                hidden={activeTabId !== i}
              />
            ))}
        </StyledTabs>
      ) : (
        <Timeline items={data} type="education" />
      )}
    </StyledContainer>
  );
};

Education.propTypes = {
  data: PropTypes.array.isRequired,
};

export default Education;