import React from 'react';
import PropTypes from 'prop-types';
import {
  StyledFilterContainer,
  StyledTagsWrapper,
  StyledTagButton,
  StyledTagCount,
  StyledFilterControls,
  StyledFilterModeToggle,
  StyledClearButton,
  StyledFilterStatus,
} from '../styles/featured-style';

const TagsList = ({
  allTags,
  selectedTags,
  tagCounts,
  filterMode,
  onTagClick,
  onFilterModeToggle,
  onClearFilters,
  filteredCount,
  totalProjects,
}) => {
  // Don't render if there's only one or no tags
  if (!allTags || allTags.length <= 1) {
    return null;
  }

  const hasActiveFilters = selectedTags.length > 0;

  return (
    <StyledFilterContainer>
      <StyledTagsWrapper>
        {allTags.map((tag) => {
          const isSelected = selectedTags.includes(tag);
          const count = tagCounts[tag] || 0;

          return (
            <StyledTagButton
              key={tag}
              $isSelected={isSelected}
              onClick={() => onTagClick(tag)}
              aria-pressed={isSelected}
              aria-label={`Filter by ${tag}${isSelected ? ' (selected)' : ''}`}
            >
              {tag}
              <StyledTagCount $isSelected={isSelected}>
                {count}
              </StyledTagCount>
            </StyledTagButton>
          );
        })}
      </StyledTagsWrapper>

      <StyledFilterControls>
        {hasActiveFilters && selectedTags.length > 1 && (
          <StyledFilterModeToggle
            onClick={onFilterModeToggle}
            aria-label={`Filter mode: ${filterMode === 'AND' ? 'Match all tags' : 'Match any tag'}`}
          >
            Match: <span className="mode">{filterMode === 'AND' ? 'All' : 'Any'}</span>
          </StyledFilterModeToggle>
        )}

        <StyledClearButton
          onClick={onClearFilters}
          disabled={!hasActiveFilters}
          aria-label="Clear all filters"
        >
          Clear{hasActiveFilters ? ` (${selectedTags.length})` : ''}
        </StyledClearButton>

        {hasActiveFilters && (
          <StyledFilterStatus>
            Showing {filteredCount} of {totalProjects} projects
          </StyledFilterStatus>
        )}
      </StyledFilterControls>
    </StyledFilterContainer>
  );
};

TagsList.propTypes = {
  allTags: PropTypes.array.isRequired,
  selectedTags: PropTypes.array.isRequired,
  tagCounts: PropTypes.object.isRequired,
  filterMode: PropTypes.oneOf(['AND', 'OR']).isRequired,
  onTagClick: PropTypes.func.isRequired,
  onFilterModeToggle: PropTypes.func.isRequired,
  onClearFilters: PropTypes.func.isRequired,
  filteredCount: PropTypes.number.isRequired,
  totalProjects: PropTypes.number.isRequired,
};

export default TagsList;
