import React from 'react';
import PropTypes from 'prop-types';
import { StyledTabButton } from '../styles/education-styles';

const EducationTabButton = React.forwardRef(({ isActive, onClick, id, tabIndex, children }, ref) => (
    <StyledTabButton
        isActive={isActive}
        onClick={onClick}
        ref={ref}
        id={id}
        role="tab"
        aria-selected={isActive ? true : false}
        aria-controls={`${id}-panel`}
        tabIndex={tabIndex}
    >
        <span>{children}</span>
    </StyledTabButton>
));

EducationTabButton.propTypes = {
    isActive: PropTypes.bool.isRequired,
    onClick: PropTypes.func.isRequired,
    id: PropTypes.string.isRequired,
    tabIndex: PropTypes.string.isRequired,
    children: PropTypes.node.isRequired,
};

export default EducationTabButton;
