import { GatsbyImage } from "gatsby-plugin-image";
import styled from 'styled-components';
import { theme, mixins, media, Section } from '@styles';

const { colors, fontSizes, fonts } = theme;

export const StyledContainer = styled(Section)`
  position: relative;
  max-width: 1000px;
`;

export const StyledTabs = styled.div`
  display: flex;
  align-items: flex-start;
  position: relative;
  ${media.thone`
    display: block;
  `};
`;

export const StyledTabList = styled.ul`
  display: block;
  position: relative;
  width: max-content;
  z-index: 3;
  padding: 0;
  margin: 0;
  list-style: none;

  ${media.thone`
    display: flex;
    overflow-x: scroll;
    margin-bottom: 30px;
    width: calc(100% + 100px);
    margin-left: -50px;
  `};
  ${media.phablet`
    width: calc(100% + 50px);
    margin-left: -25px;
  `};

  li {
    &:first-of-type {
      ${media.thone`
        margin-left: 50px;
      `};
      ${media.phablet`
        margin-left: 25px;
      `};
    }
    &:last-of-type {
      ${media.thone`
        padding-right: 50px;
      `};
      ${media.phablet`
        padding-right: 25px;
      `};
    }
  }
`;

export const StyledTabButton = styled.button`
  ${mixins.link};
  display: flex;
  align-items: center;
  width: 100%;
  background-color: transparent;
  height: ${theme.tabHeight}px;
  padding: 0 20px 2px;
  transition: ${theme.transition};
  border-left: 2px solid var(--color-bg-lightest);
  text-align: left;
  white-space: nowrap;
  font-family: ${fonts.SFMono};
  font-size: ${fontSizes.smish};
  color: ${props => (props.isActive ? 'var(--color-accent)' : 'var(--color-text)')};
  ${media.tablet`padding: 0 15px 2px;`};
  ${media.thone`
    ${mixins.flexCenter};
    padding: 0 15px;
    text-align: center;
    border-left: 0;
    border-bottom: 2px solid var(--color-bg-lightest);
    min-width: 120px;
  `};
  &:hover,
  &:focus {
    background-color: var(--color-bg-light);
  }
`;

export const StyledHighlight = styled.span`
  display: block;
  background: var(--color-accent);
  width: 2px;
  height: ${theme.tabHeight}px;
  border-radius: ${theme.borderRadius};
  position: absolute;
  top: 0;
  left: 0;
  transition: transform 0.25s cubic-bezier(0.645, 0.045, 0.355, 1);
  transition-delay: 0.1s;
  z-index: 10;
  transform: translateY(
    ${props => (props.activeTabId > 0 ? props.activeTabId * theme.tabHeight : 0)}px
  );
  ${media.thone`
    width: 100%;
    max-width: ${theme.tabWidth}px;
    height: 2px;
    top: auto;
    bottom: 0;
    transform: translateX(
      ${props => (props.activeTabId > 0 ? props.activeTabId * theme.tabWidth : 0)}px
    );
    margin-left: 50px;
  `};
  ${media.phablet`
    margin-left: 25px;
  `};
`;

export const StyledTabContent = styled.div`
  position: relative;
  width: 100%;
  height: auto;
  padding-top: 12px;
  padding-left: 30px;
  ${media.tablet`padding-left: 20px;`};
  ${media.thone`padding-left: 0;`};

  ul {
    ${mixins.fancyList};
  }
  a {
    ${mixins.inlineLink};
  }
`;

// New CSS rules

export const StyledGrid = styled.div`
  margin-top: 0px;
  margin-left: 10%;

  .projects {
    display: grid;
    grid-template-columns: repeat(auto-fill, 120px);
    grid-gap: 20px;
    position: relative;
    ${media.desktop`grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));`};
  }
`;

export const StyledProjectInner = styled.div`
  ${mixins.boxShadow};
  ${mixins.flexBetween};
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  padding: 0.25rem 0.25rem;
  height: 120px;
  width: 120px;
  border-radius: ${theme.borderRadius};
  transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);
  background-color: var(--color-bg-light);
  border: 1px solid var(--color-bg-lightest);
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(
      135deg,
      transparent 0%,
      rgba(100, 255, 218, 0.03) 50%,
      transparent 100%
    );
    opacity: 0;
    transition: opacity 0.3s ease;
  }
`;

export const StyledProject = styled.div`
  transition: ${theme.transition};
  cursor: default;
  &:hover,
  &:focus {
    outline: 0;
    ${StyledProjectInner} {
      transform: translateY(-5px) scale(1.02);
      border-color: var(--color-accent);
      box-shadow: 0 10px 30px -15px rgba(2, 12, 27, 0.7),
                  0 0 20px rgba(100, 255, 218, 0.15);

      &::before {
        opacity: 1;
      }
    }
  }
`;

export const StyledFeaturedImg = styled(GatsbyImage)`
  width: 80%;
  height: auto;
  max-width: 100%;
  max-height: 80%;
  vertical-align: middle;
  border-radius: ${theme.borderRadius};
  object-fit: cover;
  position: relative;
`;

export const StyledProjectName = styled.h5`
  margin: 0;
  margin-top: 10px;
  font-size: ${fontSizes.lg};
  color: var(--color-accent);
  text-align: center; /* Center align the text */
  white-space: nowrap; /* Prevents text wrapping if necessary */
  overflow: hidden;
  text-overflow: ellipsis; /* Adds ellipsis if text is too long */
`;