import React, { useState, useEffect } from 'react';
import styled, { keyframes } from 'styled-components';
import { theme, media } from '@styles';
import { useTheme } from '@context';
import { IconSun, IconMoon } from '@components/icons';

const slideIn = keyframes`
  from {
    transform: translateY(100%) translateX(-50%);
    opacity: 0;
  }
  to {
    transform: translateY(0) translateX(-50%);
    opacity: 1;
  }
`;

const slideOut = keyframes`
  from {
    transform: translateY(0) translateX(-50%);
    opacity: 1;
  }
  to {
    transform: translateY(100%) translateX(-50%);
    opacity: 0;
  }
`;

const StyledToast = styled.div`
  position: fixed;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-bg-light);
  border: 1px solid var(--color-accent);
  border-radius: ${theme.borderRadius};
  padding: 12px 24px;
  display: flex;
  align-items: center;
  gap: 12px;
  z-index: 100;
  box-shadow: 0 10px 30px -15px var(--color-shadow);
  animation: ${props => (props.$isExiting ? slideOut : slideIn)} 0.3s ease forwards;
  pointer-events: none;

  ${media.tablet`
    bottom: 20px;
    padding: 10px 20px;
  `}

  svg {
    width: 20px;
    height: 20px;
    color: var(--color-accent);
  }
`;

const StyledText = styled.span`
  font-family: ${theme.fonts.SFMono};
  font-size: ${theme.fontSizes.sm};
  color: var(--color-text-lightest);
  white-space: nowrap;
`;

const ThemeToast = () => {
  const { isDarkMode, isInitialized } = useTheme();
  const [show, setShow] = useState(false);
  const [isExiting, setIsExiting] = useState(false);
  const [isFirstRender, setIsFirstRender] = useState(true);

  useEffect(() => {
    // Skip the first render (initial load)
    if (isFirstRender && isInitialized) {
      setIsFirstRender(false);
      return;
    }

    // Only show toast after initial load
    if (!isFirstRender && isInitialized) {
      setShow(true);
      setIsExiting(false);

      // Start exit animation after 1.5s
      const exitTimer = setTimeout(() => {
        setIsExiting(true);
      }, 1500);

      // Hide completely after animation
      const hideTimer = setTimeout(() => {
        setShow(false);
      }, 1800);

      return () => {
        clearTimeout(exitTimer);
        clearTimeout(hideTimer);
      };
    }
  }, [isDarkMode, isInitialized]);

  if (!show) return null;

  return (
    <StyledToast $isExiting={isExiting}>
      {isDarkMode ? <IconMoon /> : <IconSun />}
      <StyledText>
        {isDarkMode ? 'Dark mode enabled' : 'Light mode enabled'}
      </StyledText>
    </StyledToast>
  );
};

export default ThemeToast;
